export default {
  props: {
    allDates: Array,
    bookedByDialog: Boolean
  },
  data() {
    return {};
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    get_date(val) {
      const d = new Date(parseInt(val));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return +year + "-" + (+month <= 9 ? "0" + month : month) + "-" + (+date <= 9 ? "0" + date : date);
    }
  }
};
